from rcb_brush import Session
s=Session(instance='/app/instance.json');a=np.load('/app/output/trajectory_fixed35.npz')['actions'];s.reset()
for x in a:s.step(x)
s.painter.finish()
im=cv2.imread('/app/target.png');T=(cv2.cvtColor(im,cv2.COLOR_BGR2GRAY)<128).astype(np.uint8);n,L,stats,_=cv2.connectedComponentsWithStats(T,8)
for j,d in enumerate(s.strokes()):
 m=np.zeros((1024,1024),np.uint8);r,c=d['mask_bbox'];m[r:r+d['mask'].shape[0],c:c+d['mask'].shape[1]]=(d['mask']>=128).astype(np.uint8)
 target=(L==j+1).astype(np.uint8);best=(0,None,None)
 for dy in range(-5,6):
  for dx in range(-5,6):
   shifted=np.zeros_like(m); ys=slice(max(0,dy),min(1024,1024+dy)); xs=slice(max(0,dx),min(1024,1024+dx));
   y0=max(0,-dy);y1=min(1024,1024-dy);x0=max(0,-dx);x1=min(1024,1024-dx);shifted[ys,xs]=m[y0:y1,x0:x1]
   I=np.count_nonzero(shifted&target);U=np.count_nonzero(shifted|target);iou=I/U if U else 0
   if iou>best[0]:best=(iou,dx,dy)
 print(j,'best comp',best)
PY

